package com.bananalab.lite;
import android.app.*;import android.app.job.*;import android.content.*;import android.os.*;import org.json.*;
/** User-visible continuous learning; Android owns lifetime and scheduling. */
final class LearningLoop{
 static final Object STORE=new Object();static final int JOB=6601;static volatile boolean busy;static volatile int visible;static volatile Thread worker;static volatile boolean serviceRunning;
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-continuous-learning",0);}
 static boolean enabled(Context c){return prefs(c).getBoolean("enabled",true);}
 static void status(Context c,String text){prefs(c).edit().putString("status",text).putLong("updated",System.currentTimeMillis()).apply();}
 static JSONObject portable(Context c)throws Exception{synchronized(STORE){return new JSONObject().put("version",1).put("enabled",enabled(c)).put("round",prefs(c).getInt("round",1)).put("day",prefs(c).getLong("day",System.currentTimeMillis()/LearningPlan.DAY_MS)).put("nextReview",prefs(c).getLong("nextReview",0)).put("accepted",prefs(c).getInt("accepted",0)).put("rejected",prefs(c).getInt("rejected",0)).put("history",new JSONArray(prefs(c).getString("history","[]")));}}
 static void validate(JSONObject p)throws Exception{RuntimeProgram.keys(p,"version","enabled","round","day","nextReview","accepted","rejected","history");if(p.getInt("version")!=1||p.getInt("round")<1||p.getInt("round")>3||p.getLong("day")<0||p.getLong("nextReview")<0||p.getInt("accepted")<0||p.getInt("rejected")<0||p.getJSONArray("history").length()>12||p.toString().length()>65536)throw new java.io.IOException("Progreso continuo inválido");p.getBoolean("enabled");JSONArray history=p.getJSONArray("history");for(int i=0;i<history.length();i++){JSONObject h=history.getJSONObject(i);if(!h.getString("sourceId").matches("[a-f0-9]{64}")||!h.getString("sourceSha256").matches("[a-f0-9]{64}")||!h.getString("labelOrigin").equals("literal_source_not_model")||h.getString("evidence").length()>700||h.getString("attempt").length()>512)throw new java.io.IOException("Ejercicio portable inválido");}}
 static void restore(Context c,JSONObject p)throws Exception{synchronized(STORE){validate(p);if(prefs(c).contains("enabled"))return;if(!prefs(c).edit().putBoolean("enabled",p.getBoolean("enabled")).putInt("round",p.getInt("round")).putLong("day",p.getLong("day")).putLong("nextReview",p.getLong("nextReview")).putInt("accepted",p.getInt("accepted")).putInt("rejected",p.getInt("rejected")).putString("history",p.getJSONArray("history").toString()).commit())throw new java.io.IOException("No pude restaurar el aprendizaje continuo");}}
 static void result(Context c,JSONObject report)throws Exception{synchronized(STORE){SharedPreferences.Editor e=prefs(c).edit();String key=report.getBoolean("accepted")?"accepted":"rejected";e.putInt(key,Math.min(100000000,prefs(c).getInt(key,0)+1));if(report.has("exercise")){JSONObject x=new JSONObject(report.getJSONObject("exercise").toString()).put("acceptedWeights",report.getBoolean("accepted")).put("time",System.currentTimeMillis());JSONArray old=new JSONArray(prefs(c).getString("history","[]")),next=new JSONArray();for(int i=Math.max(0,old.length()-11);i<old.length();i++)next.put(old.getJSONObject(i));next.put(x);e.putString("history",next.toString());}if(!e.commit())throw new java.io.IOException("Modelo evaluado; falta guardar su registro continuo");}}
 static String conditions(Context c){Intent b=c.registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));int level=b==null?-1:b.getIntExtra("level",-1),scale=b==null?100:b.getIntExtra("scale",100);int percentage=level<0||scale<=0?-1:(int)(100L*level/scale);boolean charging=b!=null&&b.getIntExtra("plugged",0)!=0;PowerManager power=(PowerManager)c.getSystemService(Context.POWER_SERVICE);return LearningPlan.resources(percentage,charging,power!=null&&power.isPowerSaveMode(),busy);}
 static void check(Context c)throws Exception{if(!enabled(c))throw new ReadingBudget.Paused("aprendizaje continuo pausado");String why=conditions(c);if(!why.isEmpty())throw new ReadingBudget.Paused(why);}
 static void setBusy(boolean value){busy=value;}
 static void pause(Context c)throws Exception{if(!prefs(c).edit().putBoolean("enabled",false).commit())throw new java.io.IOException("No pude guardar la pausa; no la confirmé");synchronized(ReadingTraining.LOCK){JSONObject s=ReadingTraining.state(c);s.put("enabled",false);ReadingTraining.save(c,s);}Thread t=worker;if(t!=null)t.interrupt();if(!(c instanceof NotebookDisk.Provider)){c.stopService(new Intent(c,LearningService.class));configure(c);}status(c,"Pausado por vos");}
 static void enable(Context c)throws Exception{if(!prefs(c).edit().putBoolean("enabled",true).commit())throw new java.io.IOException("No pude activar el modo continuo");synchronized(ReadingTraining.LOCK){JSONObject s=ReadingTraining.state(c);s.put("enabled",true);ReadingTraining.save(c,s);}wake(c);}
 static void configure(Context c){if(c instanceof NotebookDisk.Provider)return;try{JobScheduler jobs=(JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE);if(jobs==null)return;if(!enabled(c)){jobs.cancel(JOB);return;}JobInfo found=null;for(JobInfo j:jobs.getAllPendingJobs())if(j.getId()==JOB)found=j;if(found==null){int scheduled=jobs.schedule(new JobInfo.Builder(JOB,new ComponentName(c,LearningJob.class)).setPeriodic(15*60*1000L).setPersisted(true).build());if(scheduled!=JobScheduler.RESULT_SUCCESS)status(c,"Android no aceptó la tarea de reanudación; abrí Banana para continuar");}}catch(Exception e){status(c,"Reanudación pendiente de Android: "+e.getClass().getSimpleName());}}
 static void wake(Context c){if(c instanceof NotebookDisk.Provider)return;configure(c);if(!enabled(c)||serviceRunning||visible==0)return;try{Intent i=new Intent(c,LearningService.class);if(Build.VERSION.SDK_INT>=26)c.startForegroundService(i);else c.startService(i);}catch(Exception e){status(c,"Android aplazó el servicio; la tarea programada podrá continuar: "+e.getClass().getSimpleName());}}
 static void opened(Activity a){visible++;if(a instanceof BananaActivity){if(Build.VERSION.SDK_INT>=33&&!prefs(a).getBoolean("notificationAsked",false)){prefs(a).edit().putBoolean("notificationAsked",true).apply();if(a.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)a.requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},6601);}}wake(a.getApplicationContext());}
 static void closed(){visible=Math.max(0,visible-1);}
 static boolean prepare(Context c)throws Exception{synchronized(ReadingTraining.LOCK){if(!ReadingTraining.state(c).getBoolean("enabled"))return false;ReadingTraining.collect(c);JSONObject state=ReadingTraining.state(c);if(state.getJSONArray("jobs").length()>0)return true;long now=System.currentTimeMillis(),day=now/LearningPlan.DAY_MS,priorDay=prefs(c).getLong("day",day),due=prefs(c).getLong("nextReview",0);int round=prefs(c).getInt("round",1);if(due==0){prefs(c).edit().putLong("day",day).putLong("nextReview",now+LearningPlan.REVIEW_MS).commit();return false;}if(!LearningPlan.review(now,due,round,priorDay))return false;if(NotebookDisk.of(c).index.count()==0)return false;round=priorDay==day?round+1:1;state.put("done",new JSONArray());ReadingTraining.save(c,state);prefs(c).edit().putInt("round",round).putLong("day",day).putLong("nextReview",now+LearningPlan.REVIEW_MS).commit();ReadingTraining.collect(c);return ReadingTraining.state(c).getJSONArray("jobs").length()>0;}}
 static boolean cycle(Context c)throws Exception{DurableCode.awaitReady();check(c);if(!prepare(c)){status(c,"Sin bloques pendientes; esperando fuentes nuevas o el próximo repaso espaciado");return false;}status(c,"Entrenando un bloque y resolviendo ejercicios de las fuentes");String receipt=ReadingTraining.background(c);status(c,receipt);return true;}
 static void forget(Context c)throws Exception{if(!prefs(c).edit().remove("history").remove("nextReview").remove("round").remove("day").commit())throw new java.io.IOException("No pude limpiar el historial de ejercicios");}
 static String summary(Context c)throws Exception{JSONObject p=portable(c);return "Aprendizaje continuo: "+(enabled(c)?"activado":"pausado")+"\n"+prefs(c).getString("status","Esperando abrir Banana")+"\nCheckpoints aceptados: "+p.getInt("accepted")+" · candidatos rechazados: "+p.getInt("rejected")+" · ejercicios recientes: "+p.getJSONArray("history").length()+"\nRepasos: hasta tres recorridos diarios por contenido disponible, separados al menos15min al agotar la cola. Android puede suspender el proceso. Las mejoras locales no demuestran inteligencia general.";}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String q=NaturalCoding.normalize(input);boolean on=q.matches("(?:activa|activar|inicia|iniciar|reanuda|reanudar) (?:el )?(?:aprendizaje continuo|entrenamiento continuo)|(?:aprende|entrena|segui aprendiendo|continua aprendiendo) (?:todo el tiempo|en segundo plano)");boolean off=q.matches("(?:pausa|pausar|detene|desactiva) (?:el )?(?:aprendizaje continuo|entrenamiento continuo)|deja de (?:aprender|entrenar) en segundo plano");boolean show=q.matches("(?:estado|como va) (?:del |el )?(?:aprendizaje continuo|entrenamiento continuo)|(?:mostrame|muestra|ver) (?:tus |los )?ejercicios(?: de aprendizaje)?");if(!on&&!off&&!show)return null;try{if(on)enable(c);if(off)pause(c);String text=summary(c);if(q.contains("ejercicios")){JSONArray h=portable(c).getJSONArray("history");for(int i=Math.max(0,h.length()-3);i<h.length();i++){JSONObject x=h.getJSONObject(i);text+="\n\nPregunta: "+x.getString("evalQuestion")+"\nIntento propio: "+x.getString("attempt")+"\nRespuesta de la fuente: "+x.getString("answer")+"\nCoincidencia exacta: "+x.getBoolean("correctExact")+"\nFuente: "+x.getString("source");}}return MobileCore.say(c,text,"aprendizaje_continuo");}catch(Exception e){return MobileCore.say(c,"No pude cambiar el modo continuo: "+AndroidRepair.summary(e),"aprendizaje_continuo");}}
}
